+<!DOCTYPE html>
+<html lang="en">
+<head>
+    <meta charset="UTF-8">
+    <meta name="viewport" content="width=device-width, initial-scale=1.0">
+    <title>Cyber-Grid Snake Game</title>
+    <style>
+        body {
+            display: flex;
+            justify-content: center;
+            align-items: center;
+            min-height: 100vh;
+            margin: 0;
+            padding: 20px;
+            background: #090d16;
+        }
+        .game-container {
+            background: rgba(16, 24, 40, 0.75);
+            backdrop-filter: blur(20px);
+            padding: 20px;
+            border-radius: 10px;
+            box-shadow: 0 0 30px rgba(56, 189, 248, 0.4);
+        }
+        .game-over-overlay {
+            display: none;
+            position: absolute;
+            top: 0;
+            left: 0;
+            width: 100%;
+            height: 100%;
+            background: rgba(0, 0, 0, 0.5);
+            justify-content: center;
+            align-items: center;
+        }
+        .start-game-overlay {
+            position: absolute;
+            top: 0;
+            left: 0;
+            width: 100%;
+            height: 100%;
+            background: rgba(0, 0, 0, 0.5);
+            justify-content: center;
+            align-items: center;
+        }
+        .hud {
+            display: flex;
+            justify-content: space-between;
+            padding: 12px 20px;
+        }
+        .score {
+            font-family: 'Inter', sans-serif;
+            font-size: 24px;
+            color: #fff;
+        }
+        .high-score {
+            font-family: 'Inter', sans-serif;
+            font-size: 24px;
+            color: #fff;
+        }
+    </style>
+</head>
+<body>
+    <div class="game-container">
+        <canvas id="gameCanvas" width="400" height="400"></canvas>
+        <div class="hud">
+            <span class="score" id="score">Score: 0</span>
+            <span class="high-score" id="high-score">High Score: 0</span>
+        </div>
+        <div class="start-game-overlay">
+            <h1>Start Game</h1>
+            <button id="start-game-button">Play</button>
+        </div>
+        <div class="game-over-overlay">
+            <h1>Game Over</h1>
+            <span id="final-score"></span>
+            <button id="replay-button">Replay</button>
+        </div>
+    </div>
+    <script>
+        let canvas = document.getElementById('gameCanvas');
+        let ctx = canvas.getContext('2d');
+        let score = 0;
+        let highScore = localStorage.getItem('highScore') || 0;
+        let snake = [
+            {x: 200, y: 200},
+            {x: 190, y: 200},
+            {x: 180, y: 200}
+        ];
+        let direction = 'right';
+        let speed = 100;
+        let powerUps = [];
+        let shield = false;
+        let audioContext = new AudioContext();
+        let eatSound = new Audio('eat.mp3');
+        let gameOverSound = new Audio('gameover.mp3');
+        let scoreDisplay = document.getElementById('score');
+        let highScoreDisplay = document.getElementById('high-score');
+        let finalScoreDisplay = document.getElementById('final-score');
+        let startGameButton = document.getElementById('start-game-button');
+        let replayButton = document.getElementById('replay-button');
+        let startGameOverlay = document.querySelector('.start-game-overlay');
+        let gameOverOverlay = document.querySelector('.game-over-overlay');
+        
+        startGameButton.addEventListener('click', startGame);
+        replayButton.addEventListener('click', replayGame);
+        document.addEventListener('keydown', handleKeydown);
+        
+        function startGame() {
+            startGameOverlay.style.display = 'none';
+            update();
+        }
+        
+        function replayGame() {
+            gameOverOverlay.style.display = 'none';
+            score = 0;
+            snake = [
+                {x: 200, y: 200},
+                {x: 190, y: 200},
+                {x: 180, y: 200}
+            ];
+            direction = 'right';
+            speed = 100;
+            powerUps = [];
+            shield = false;
+            update();
+        }
+        
+        function handleKeydown(event) {
+            if (event.key === 'ArrowUp' && direction !== 'down') {
+                direction = 'up';
+            } else if (event.key === 'ArrowDown' && direction !== 'up') {
+                direction = 'down';
+            } else if (event.key === 'ArrowLeft' && direction !== 'right') {
+                direction = 'left';
+            } else if (event.key === 'ArrowRight' && direction !== 'left') {
+                direction = 'right';
+            }
+        }
+        
+        function update() {
+            ctx.clearRect(0, 0, canvas.width, canvas.height);
+            for (let i = 0; i < snake.length; i++) {
+                ctx.fillStyle = 'rgba(0, 255, 0, 0.5)';
+                ctx.fillRect(snake[i].x, snake[i].y, 10, 10);
+            }
+            
+            let head = snake[0];
+            if (direction === 'up') {
+                head.y -= 10;
+            } else if (direction === 'down') {
+                head.y += 10;
+            } else if (direction === 'left') {
+                head.x -= 10;
+            } else if (direction === 'right') {
+                head.x += 10;
+            }
+            
+            if (head.x < 0 || head.x >= canvas.width || head.y < 0 || head.y >= canvas.height) {
+                gameOver();
+            }
+            
+            for (let i = 1; i < snake.length; i++) {
+                if (head.x === snake[i].x && head.y === snake[i].y) {
+                    gameOver();
+                }
+            }
+            
+            scoreDisplay.textContent = `Score: ${score}`;
+            highScoreDisplay.textContent = `High Score: ${highScore}`;
+            
+            if (score > highScore) {
+                highScore = score;
+                localStorage.setItem('highScore', highScore);
+            }
+            
+            setTimeout(update, speed);
+        }
+        
+        function gameOver() {
+            gameOverSound.play();
+            gameOverOverlay.style.display = 'flex';
+            finalScoreDisplay.textContent = `Final Score: ${score}`;
+        }
+    </script>
+</body>
+</html>

